<template>
      <div class="login-wrapper">
          <form v-if="step === 'login'" @submit.prevent="handleLogin">
                <div class="input-box">
                        <input type="email" v-model="form.email" required />
                                <label>Email</label>
                                        <i class="bx bxs-envelope"></i>
                                              </div>

                                                    <div class="input-box">
                                                            <input type="password" v-model="form.password" required />
                                                                    <label>Password</label>
                                                                            <i class="bx bxs-lock-alt"></i>
                                                                                  </div>

                                                                                        <div v-if="errorMessage" class="error-msg">
                                                                                                {{ errorMessage }}
                                                                                                      </div>

                                                                                                            <div class="forgot-link" v-if="showForgotOption">
                                                                                                                    <a href="#" @click.prevent="startForgotPassword">Forgot Password?</a>
                                                                                                                          </div>

                                                                                                                                <button type="submit" class="btn">Login</button>

                                                                                                                                      <div class="logreg-link">
                                                                                                                                              <p>Don't have an account? <a href="#" @click.prevent="$emit('switchToRegister')">Sign Up</a></p>
                                                                                                                                                    </div>
                                                                                                                                                        </form>

                                                                                                                                                            <form v-else-if="step === 'verify_code'" @submit.prevent="handleVerifyCode">
                                                                                                                                                                  <p class="info-text">
                                                                                                                                                                          A verification code was sent to <strong>{{ form.email }}</strong>
                                                                                                                                                                                </p>
                                                                                                                                                                                      
                                                                                                                                                                                            <div class="code-alert">
                                                                                                                                                                                                    🔑 Simulated Email Code: <strong>{{ generatedCode }}</strong>
                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                <div class="input-box">
                                                                                                                                                                                                                        <input type="text" v-model="userEnteredCode" maxlength="6" required />
                                                                                                                                                                                                                                <label>Enter 6-digit Code</label>
                                                                                                                                                                                                                                        <i class="bx bx-key"></i>
                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                    <div v-if="errorMessage" class="error-msg">
                                                                                                                                                                                                                                                            {{ errorMessage }}
                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                        <button type="submit" class="btn">Verify & Login</button>
                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                    <div class="logreg-link">
                                                                                                                                                                                                                                                                                            <p><a href="#" @click.prevent="step = 'login'">Back to Login</a></p>
                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                      </form>
                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                        </template>

                                                                                                                                                                                                                                                                                                        <script setup>
                                                                                                                                                                                                                                                                                                        import { reactive, ref } from 'vue'
                                                                                                                                                                                                                                                                                                        import { useRouter } from 'vue-router'

                                                                                                                                                                                                                                                                                                        const router = useRouter()
                                                                                                                                                                                                                                                                                                        defineEmits(['switchToRegister'])

                                                                                                                                                                                                                                                                                                        const form = reactive({
                                                                                                                                                                                                                                                                                                          email: '',
                                                                                                                                                                                                                                                                                                            password: ''
                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                            const step = ref('login')
                                                                                                                                                                                                                                                                                                            const errorMessage = ref('')
                                                                                                                                                                                                                                                                                                            const showForgotOption = ref(false)
                                                                                                                                                                                                                                                                                                            const generatedCode = ref('')
                                                                                                                                                                                                                                                                                                            const userEnteredCode = ref('')
                                                                                                                                                                                                                                                                                                            const foundUser = ref(null)

                                                                                                                                                                                                                                                                                                            const handleLogin = async () => {
                                                                                                                                                                                                                                                                                                              errorMessage.value = ''
                                                                                                                                                                                                                                                                                                                showForgotOption.value = false

                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                      const rawUrl = 'https://raw.githubusercontent.com/esraaelshamy246-afk/medical-donation-platform/1e59da960820c93cd04e517325623065eca2cba1/db.json'
                                                                                                                                                                                                                                                                                                                          const res = await fetch(rawUrl)
                                                                                                                                                                                                                                                                                                                              const remoteData = await res.json()

                                                                                                                                                                                                                                                                                                                                  const localUsers = JSON.parse(localStorage.getItem('registered_users') || '[]')
                                                                                                                                                                                                                                                                                                                                      const allUsers = [...(remoteData.users || []), ...localUsers]

                                                                                                                                                                                                                                                                                                                                          const user = allUsers.find(u => u.email.toLowerCase() === form.email.toLowerCase())

                                                                                                                                                                                                                                                                                                                                              if (!user) {
                                                                                                                                                                                                                                                                                                                                                    errorMessage.value = "Email doesn't exist. Please Sign Up to create an account!"
                                                                                                                                                                                                                                                                                                                                                          return
                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                  if (user.password && user.password !== form.password) {
                                                                                                                                                                                                                                                                                                                                                                        errorMessage.value = "Incorrect password!"
                                                                                                                                                                                                                                                                                                                                                                              showForgotOption.value = true
                                                                                                                                                                                                                                                                                                                                                                                    foundUser.value = user
                                                                                                                                                                                                                                                                                                                                                                                          return
                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                  localStorage.setItem('user', JSON.stringify(user))
                                                                                                                                                                                                                                                                                                                                                                                                      router.push('/dashboard')

                                                                                                                                                                                                                                                                                                                                                                                                        } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                            console.error('Login error:', error)
                                                                                                                                                                                                                                                                                                                                                                                                                errorMessage.value = "Error connecting to server. Try again."
                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                  const startForgotPassword = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                    generatedCode.value = Math.floor(100000 + Math.random() * 900000).toString()
                                                                                                                                                                                                                                                                                                                                                                                                                      step.value = 'verify_code'
                                                                                                                                                                                                                                                                                                                                                                                                                        errorMessage.value = ''
                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                        const handleVerifyCode = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                          if (userEnteredCode.value === generatedCode.value) {
                                                                                                                                                                                                                                                                                                                                                                                                                              localStorage.setItem('user', JSON.stringify(foundUser.value))
                                                                                                                                                                                                                                                                                                                                                                                                                                  router.push('/dashboard')
                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                        errorMessage.value = "Invalid verification code. Check the code and try again."
                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                          </script>

