                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .logreg-link p a {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              color: #0ef;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                text-decoration: none;
